{"path":"assets/css/styles.css","content":"/* Glass morphism + mystic modern palette */
:root{
  --bg1:#0f1722;
  --glass: rgba(255,255,255,0.06);
  --glass-2: rgba(255,255,255,0.04);
  --accent1:#7BE1C7;
  --accent2:#8DA4FF;
  --muted:#a6b0c2;
  --card-radius:16px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#eaf0f8;background:linear-gradient(180deg,var(--bg1) 0%, #08101a 100%);}
.page-bg{position:fixed;inset:0;z-index:-2;overflow:hidden}
.pattern{position:absolute;inset:0;background-image:url('../img/pattern.svg');background-repeat:repeat;opacity:0.16;filter:hue-rotate(10deg) saturate(110%);}
.container{max-width:1100px;margin:0 auto;padding:32px}
.site-header{position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);backdrop-filter: blur(6px);border-bottom:1px solid rgba(255,255,255,0.03)}
.site-header .container{display:flex;align-items:center;gap:24px}
.brand{display:flex;align-items:center;gap:12px;padding:10px 8px;text-decoration:none;color:inherit}
.logo-mark{width:44px;height:44px;border-radius:10px;background:linear-gradient(135deg,var(--accent1),var(--accent2));box-shadow:0 6px 18px rgba(141,164,255,0.12) inset}
.brand-text small.tag{display:block;color:var(--muted);font-size:12px}
.main-nav ul{display:flex;gap:14px;list-style:none;padding:0;margin:0}
.main-nav a{color:#dfe9ff;text-decoration:none;font-weight:600;padding:10px;border-radius:10px}
.main-nav a:hover{background:rgba(255,255,255,0.02)}
.header-cta .phone{color:var(--accent2);text-decoration:none;font-weight:700}
.hero{padding:64px 0}
.glass-card{background:linear-gradient(180deg, rgba(255,255,255,0.03), rgba(255,255,255,0.02));border-radius:var(--card-radius);padding:28px;box-shadow:0 8px 30px rgba(2,6,23,0.6);border:1px solid rgba(255,255,255,0.04);backdrop-filter: blur(10px);}
.hero-grid{display:grid;grid-template-columns:1fr 420px;gap:32px;align-items:center}
.hero-copy h1{font-size:clamp(28px,4vw,44px);margin:0 0 12px;color:#fff}
.hero-copy .lead{color:var(--muted);margin-bottom:18px}
.btn{display:inline-block;padding:12px 18px;border-radius:12px;text-decoration:none;font-weight:700}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#072031;box-shadow:0 8px 20px rgba(139,152,255,0.12)}
.btn.ghost{background:transparent;border:1px solid rgba(255,255,255,0.04);color:#cfe6ff}
.small{color:var(--muted);font-size:13px;margin-top:10px}
.hero-ripple{display:flex;align-items:center;justify-content:center}
.hero-art{width:100%;height:260px}
.myth-truth{padding:48px 0;color:#e6f3ff}
.myth-truth h2{margin-bottom:6px}
.myth-truth .cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin-top:18px}
.card{background:var(--glass-2);padding:18px;border-radius:12px;border:1px solid rgba(255,255,255,0.02)}
.card h3{margin:0 0 8px;color:#fff}
.card .truth{color:var(--muted);font-size:14px}
.pillars{padding:36px 0}
.pillar-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:18px;list-style:none;padding:0;margin:18px 0 0}
.pillar-list li{background:linear-gradient(180deg,rgba(255,255,255,0.02),transparent);padding:16px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.pillar-list strong{display:block;color:#fff;margin-bottom:6px}
.case-notes{padding:36px 0;color:#dff1ff}
.cases{display:grid;gap:14px}
.case{background:rgba(255,255,255,0.02);padding:14px;border-radius:12px;border:1px solid rgba(255,255,255,0.03)}
.case h3{margin:0 0 6px;color:#fff}
.case .case-summary{color:var(--muted);margin:0}
.disclaimer{font-size:12px;color:var(--muted);margin-top:12px}
.faq{padding:36px 0}
.accordion .item{margin-bottom:10px}
.accordion .q{width:100%;text-align:left;background:transparent;color:#eaffff;padding:12px;border-radius:10px;border:1px solid rgba(255,255,255,0.03);cursor:pointer;font-weight:700;display:flex;justify-content:space-between;align-items:center}
.accordion .a{max-height:0;overflow:hidden;background:transparent;padding:0 12px;color:var(--muted);transition:all 0.28s ease}
.accordion .item.open .a{padding:12px;color:var(--muted);max-height:260px}
.accordion .plus{color:var(--muted);font-weight:700}
.final-cta{padding:48px 0}
.cta-card{display:flex;flex-direction:column;align-items:flex-start;gap:14px}
.btn.large{padding:14px 22px;font-size:16px}
.footer-grid{display:grid;grid-template-columns:1fr 1fr 1fr;gap:12px;padding:28px 0;border-top:1px solid rgba(255,255,255,0.03)}
.muted{color:var(--muted)}
.tiny{font-size:12px;color:var(--muted)}
.site-footer{color:var(--muted);padding:20px 0}
copyright{font-size:12px}
/* responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr;}
  .main-nav ul{display:none}
  .footer-grid{grid-template-columns:1fr}
}
/* ripple helper */
.ripple{position:relative;overflow:hidden}
.ripple .ink{position:absolute;border-radius:50%;transform:scale(0);background:rgba(255,255,255,0.2);animation:ripple 0.7s linear}
@keyframes ripple{to{transform:scale(4);opacity:0}}
"}
{"path":"assets/js/main.js","content":"document.addEventListener('DOMContentLoaded',function(){
  // Year
  var y=document.getElementById('year'); if(y) y.textContent=new Date().getFullYear();

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"], a[href$=".html"]').forEach(function(a){
    a.addEventListener('click',function(e){
      var href=a.getAttribute('href');
      if(href && href.startsWith('#')){
        e.preventDefault();
        var el=document.querySelector(href);
        if(el) el.scrollIntoView({behavior:'smooth',block:'center'});
      }
    });
  });

  // Accordion FAQ
  document.querySelectorAll('.accordion .item .q').forEach(function(btn){
    btn.addEventListener('click',function(){
      var item=this.parentElement;
      var open=item.classList.contains('open');
      document.querySelectorAll('.accordion .item').forEach(function(i){i.classList.remove('open')});
      if(!open) item.classList.add('open');
    });
  });

  // Ripple effect
  function makeRipple(e){
    var btn=e.currentTarget;
    var rect=btn.getBoundingClientRect();
    var ink=document.createElement('span');
    ink.className='ink';
    var size=Math.max(rect.width,rect.height)*1.2;
    ink.style.width=size+'px';
    ink.style.height=size+'px';
    ink.style.left=(e.clientX-rect.left-size/2)+'px';
    ink.style.top=(e.clientY-rect.top-size/2)+'px';
    btn.appendChild(ink);
    setTimeout(function(){ink.remove()},700);
  }
  document.querySelectorAll('.ripple, .btn.primary').forEach(function(b){
    b.addEventListener('click',function(ev){makeRipple(ev)});
  });

  // Primary CTA identifier for analytics placeholder
  var primary=document.getElementById('primary-cta');
  if(primary){
    primary.addEventListener('click',function(){
      try{console.log('Primary CTA clicked:', primary.getAttribute('href'))}catch(e){}
    });
  }
});
"}
